// One clean lap of every circuit, in the coordinates of F1's own Position
// feed, so the track map can draw the circuit before a single car has
// covered it. service/data/circuits.json is generated by
// scripts/build-circuits.js (the outline) and scripts/build-markers.js (the
// finish line and sector ends) from F1's timing archive. The lookup key is the
// circuit's key in SessionInfo (Meeting.Circuit.Key), live or archived.

var data = null;

function load() {
  if (data) return data;
  try {
    data = require("../data/circuits.json");
  } catch (e) {
    // A build without the file just falls back to drawing the cars' trails.
    console.error("[circuits] circuits.json not loaded:", e && e.message);
    data = {};
  }
  return data;
}

// {x: [...], y: [...], short, year, markers} or null for a circuit we have no lap for.
// The feed is already north-up (scripts/check-circuits.js), so no rotation is kept.
function forKey(key) {
  if (key === null || key === undefined) return null;
  return load()[String(key)] || null;
}

// The circuit key out of a SessionInfo, or null.
function keyOf(sessionInfo) {
  var meeting = sessionInfo && sessionInfo.Meeting;
  var circuit = meeting && meeting.Circuit;
  return circuit && circuit.Key !== undefined && circuit.Key !== null ? String(circuit.Key) : null;
}

// What the app is sent: the outline once (`have` is the key it already holds
// one for), with where the finish line and the two sector ends are as indices
// into x/y. Undefined when there is nothing to send.
function outlineFor(key, have) {
  var c = forKey(key);
  if (!c || have === key) return undefined;
  return { x: c.x, y: c.y, short: c.short, year: c.year, markers: c.markers || null };
}

module.exports = { forKey: forKey, keyOf: keyOf, outlineFor: outlineFor };
